head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > calendarClass]<br/>displayDayType=image 일때 컴포넌트의 요일에 적용될 백그라운드 이미지를 설정합니다. displayDayType=text 이면 팝업 달력의 요일이 한자리 한글('일','월') 텍스트로 표시됩니다.",
    "validation" : [
        "displayDayType=image 일때 컴포넌트의 요일에 적용될 백그라운드 이미지를 설정합니다.",
        "displayDayType=text 이면 팝업 달력의 요일이 한자리 한글('일','월') 텍스트로 표시됩니다.",
        "class1 (기본값) 설정 시 팝업 달력의 요일이 세자리 영단어 대문자('SUN','MON')로 표시됩니다.",
        "class2 설정 시 팝업 달력의 요일이 한자리 한글('일','월')로 표시됩니다.",
        "class3 설정 시 팝업 달력의 요일이 두자리 영단어('Su','Mo')가 굵게 표시됩니다.",
        "class4 설정 시 팝업 달력의 요일이 두자리 영단어('Su','Mo')로 표시됩니다.",
        "class5 설정 시 팝업 달력의 요일이 배경색이 있는 한자리 한글('일','월')로 표시됩니다.",
        "calendarValueType=yearMonth 이면 'w2calendar_classYearMonth_{속성값}', calendarValueType=year 이면 'w2calendar_classYear_{속성값}', 그 외 값이면 'w2calendar_{속성값}' 클래스가 최상위 div 의 class 속성에 추가됩니다.",
        "displayDayType, calendarClass 속성값에 관계없이 토요일은 파란색, 일요일은 빨간색으로 표시됩니다.",
        "renderType=native 이면 컴포넌트의 '연도','월' 버튼이 select 태그로 렌더링됩니다.",
        "calendarValueType=year,yearMonth 일때 calendarClass=class1 이 아니면 컴포넌트의 각 버튼 간격이 넓어집니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        calendarClass : con_calendarClass.getText(),
        displayDayType : con_displayDayType.getText(),
        calendarValueType : con_calendarValueType.getText(),
        renderType : con_renderType.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// 최상위 div 의 class 속성 확인 (calendarValueType 별 클래스명 규칙)
scwin.getRootClass = function () {
    // validation: calendarValueType=yearMonth → 'w2calendar_classYearMonth_{값}', =year → 'w2calendar_classYear_{값}', 그 외 → 'w2calendar_{값}' 클래스 부여
    wf_body_bottom.getObj("scwin").setReturnValue("[최상위 div className] " + target1.render.className);
}



// 요일 헤더 정보 확인 (영문/한글, 1/2/3 글자, 배경 이미지/색, 굵게)
scwin.getDayHeaderInfo = function () {
    let calendarRender = target1.render;
    let dayCells = calendarRender.querySelectorAll('[class*="w2calendar_day"]');
    if (!dayCells || dayCells.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue('w2calendar_day 요소가 없습니다.');
        return;
    }

    // validation: class1='SUN','MON' / class2,class5='일','월' / class3,class4='Su','Mo' / displayDayType=text → '일','월'
    let texts = [];
    dayCells.forEach((el, idx) => { if (idx < 3) texts.push(el.textContent); });
    wf_body_bottom.getObj("scwin").setReturnValue("[요일 헤더 텍스트] " + texts.map(t => "'" + t + "'").join(', '));

    // validation: displayDayType=image → 백그라운드 이미지 / class5 → 배경색 / class3 → 굵게
    const style = getComputedStyle(dayCells[0]);
    let imageFileName = '';
    const urlMatch = style.backgroundImage.match(/url\(["']?([^"']*)["']?\)/);
    if (urlMatch && urlMatch[1]) imageFileName = urlMatch[1].split('/').pop();
    wf_body_bottom.getObj("scwin").setReturnValue("[요일 헤더 스타일(첫 셀)] bgImage=" + (imageFileName || '없음') + ", bgColor=" + style.backgroundColor + ", fontWeight=" + style.fontWeight);
}



// 토요일(파란색)/일요일(빨간색) 색상 확인
scwin.getWeekendColor = function () {
    let calendarRender = target1.render;
    let sunCell = calendarRender.querySelector('[class*="w2calendar_day_sun"]');
    let satCell = calendarRender.querySelector('[class*="w2calendar_day_sat"]');

    // validation: 토요일은 파란색, 일요일은 빨간색 (displayDayType, calendarClass 무관)
    let sunColor = sunCell ? getComputedStyle(sunCell).color : 'cell 없음';
    let satColor = satCell ? getComputedStyle(satCell).color : 'cell 없음';
    wf_body_bottom.getObj("scwin").setReturnValue("[주말 색상] 일요일 color=" + sunColor + ", 토요일 color=" + satColor);
}



// renderType=native 일때 연도/월 select 태그 렌더링 여부 확인
scwin.getYearMonthRender = function () {
    let calendarRender = target1.render;
    let selectYear = calendarRender.querySelector('select[class*="w2calendar_selectbox_year"]');
    let selectMonth = calendarRender.querySelector('select[class*="w2calendar_selectbox_month"]');

    // validation: renderType=native 이면 '연도','월' 버튼이 select 태그로 렌더링됨
    wf_body_bottom.getObj("scwin").setReturnValue("[연도/월 select 렌더링 여부] 연도=" + (selectYear ? '렌더링됨' : '미렌더링') + ", 월=" + (selectMonth ? '렌더링됨' : '미렌더링'));
}



// calendarValueType=year/yearMonth + class1 외 일때 버튼 간격(셀 너비) 확인
scwin.getButtonSpacing = function () {
    let calendarRender = target1.render;
    let bodyCell = calendarRender.querySelector('td[class*="w2calendar_body"]');
    let dateCell = calendarRender.querySelector('td[class*="w2calendar_col_date"]');

    // validation: calendarValueType=year/yearMonth + calendarClass≠class1 이면 버튼 간격이 넓어짐
    let bodyW = bodyCell ? getComputedStyle(bodyCell).width : 'cell 없음';
    let dateW = dateCell ? getComputedStyle(dateCell).width : 'cell 없음';
    wf_body_bottom.getObj("scwin").setReturnValue("[버튼 셀 너비(첫 셀)] body 셀=" + bodyW + ", date 셀=" + dateW);
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getRootClass();
    scwin.getDayHeaderInfo();
    scwin.getWeekendColor();
    scwin.getYearMonthRender();
    scwin.getButtonSpacing();
}



scwin.target1_onclick = function (e) {
    setTimeout(() => {
        scwin.getRootClass();
    }, 100);
}
